#Requires -Version 7.0
. (Join-Path $PSScriptRoot 'TestHelpers.ps1');$script=Join-Path $RepoRoot '.agents/skills/story-integrity/scripts/Test-StoryNames.ps1';$result=Invoke-TestScript $script @('-Story','a-crown-of-quiet-hours','-Phase','Final','-OutputFormat','Json','-ProjectRoot',$RepoRoot);Assert-True $result.Succeeded $result.Output;$value=$result.Output|ConvertFrom-Json -Depth 20 -DateKind String;Assert-True $value.passed 'Crown final name gate did not pass.'
$rows=@(Get-Content (Join-Path $RepoRoot 'stories/NAMES.md')|Where-Object{$_-match'`a-crown-of-quiet-hours`'});Assert-Equal 4 $rows.Count 'Crown must have four registry entries.';Assert-True (-not@($rows|Where-Object{$_-notmatch'\| canon \|'}).Count) 'Every Crown registry entry must be canon.';'Name gate tests passed.'
